export type A2aTaskState =
  | 'submitted'
  | 'working'
  | 'input_required'
  | 'auth_required'
  | 'completed'
  | 'failed'
  | 'canceled'
  | 'rejected'

export type TaskAction = 'cancel' | 'resume' | 'authorize' | 'reject'

export interface TaskAgentRef {
  id: string
  slug: string
  name: string
}

export interface TaskConversationRef {
  id: string
